self.onmessage = async function (e) {
  const { url, id } = e.data;

  try {
    // 1. Fetch the CSV data
    const response = await fetch(url);

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const text = await response.text();

    // 2. Process the CSV (Heavy Lifting)
    // For a robust solution, you might use a library like PapaParse here.
    // For this example, we will do a basic split to demonstrate the worker concept.
    const lines = text.split('\n');
