      if (!line.trim()) return null;
      const values = line.split(',').map(v => v.trim());

      // Convert to object
      const row = {};
      headers.forEach((header, i) => {
        row[header] = values[i] || '';
      });
      return { id: index, ...row };
    }).filter(Boolean);

    // 3. Send processed data back to main thread
    self.postMessage({
      id,
      success: true,
      data,
      headers,
      rowCount: data.length
    });

  } catch (error) {
    // Send error back to main thread
    self.postMessage({
      id,
      success: false,
      error: error.message
    });
  }
};
